{
  "steps": [
    {
      "step_id": 1,
      "time": "06:00",
      "role": "市气象局",
      "action": "台风预警",
      "description": "市气象局监测到强台风将于24小时内登陆沿海区域，发布台风橙色预警信号，通过突发事件预警信息发布系统向公众和相关部门发布台风路径、风力、雨量及影响范围等信息，提示做好防台风准备。",
      "resources": [
        {
          "resource_type": "气象监测设备",
          "quantity": 1
        },
        {
          "resource_type": "卫星电话",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 2,
      "time": "06:15",
      "role": "市应急管理局",
      "action": "会商研判",
      "description": "市应急管理局组织气象、海洋、水务、交通、海事等部门开展台风防御会商研判，分析台风发展趋势、可能受影响区域及风险等级，形成防御工作建议，报市三防指挥部。",
      "resources": [
        {
          "resource_type": "环境监测设备",
          "quantity": 1
        },
        {
          "resource_type": "卫星电话",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 3,
      "time": "06:30",
      "role": "市三防指挥部",
      "action": "启动响应",
      "description": "市三防指挥部根据会商研判结果，决定启动防台风Ⅱ级应急响应，发布启动响应通知，要求各县区、各部门按照预案要求立即开展防台风各项防御工作，落实24小时值班和领导带班制度。",
      "resources": [
        {
          "resource_type": "卫星电话",
          "quantity": 2
        },
        {
          "resource_type": "通信设备",
          "quantity": 1
        }
      ]
    },
    {
      "step_id": 4,
      "time": "06:45",
      "role": "市三防指挥部",
      "action": "统一指挥",
      "description": "市三防指挥部成立现场指挥部，统一指挥协调气象、海洋、水务、交通、海事、公安、消防、卫健、民政等成员单位开展防台风工作，明确各工作组职责分工。",
      "resources": [
        {
          "resource_type": "指挥车辆",
          "quantity": 1
        },
        {
          "resource_type": "卫星电话",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 5,
      "time": "07:00",
      "role": "市海洋渔业局",
      "action": "船只回港",
      "description": "市海洋渔业局通过渔船监控系统和通信设备，通知所有海上作业渔船立即回港避风，要求渔船在台风登陆前全部返港，并做好渔船锚泊加固工作。",
      "resources": [
        {
          "resource_type": "卫星电话",
          "quantity": 5
        },
        {
          "resource_type": "通信设备",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 6,
      "time": "07:15",
      "role": "海事局",
      "action": "船舶管控",
      "description": "海事局发布航行警告，对辖区海域实施交通管制，禁止船舶冒险航行，引导商船、工程船等前往指定避风锚地，加强锚地船舶值班值守和动态监控。",
      "resources": [
        {
          "resource_type": "巡逻艇",
          "quantity": 2
        },
        {
          "resource_type": "通信设备",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 7,
      "time": "07:30",
      "role": "沿海各街道办事处",
      "action": "人员转移",
      "description": "沿海各街道办事处组织社区工作人员、网格员对辖区内低洼地带、危旧房屋、临时工棚、海上养殖等危险区域人员进行排查，挨家挨户通知并组织群众转移至安全区域或安置点。",
      "resources": [
        {
          "resource_type": "运输车辆",
          "quantity": 5
        },
        {
          "resource_type": "冲锋舟",
          "quantity": 3
        },
        {
          "resource_type": "帐篷",
          "quantity": 20
        }
      ]
    },
    {
      "step_id": 8,
      "time": "07:45",
      "role": "市文化和旅游局",
      "action": "景区关闭",
      "description": "市文化和旅游局通知沿海旅游景区、海滨浴场、涉水旅游项目全部关闭，疏散景区内游客，设置警示标志，禁止游客进入危险区域。",
      "resources": [
        {
          "resource_type": "运输车辆",
          "quantity": 3
        },
        {
          "resource_type": "通信设备",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 9,
      "time": "08:00",
      "role": "市教育局",
      "action": "停课指令",
      "description": "市教育局发布停课通知，要求沿海区域所有中小学、幼儿园、培训机构立即停课，做好学生留校或安全疏散安排，确保师生安全。",
      "resources": [
        {
          "resource_type": "通信设备",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 10,
      "time": "08:15",
      "role": "市住房和城乡建设局",
      "action": "工地停工",
      "description": "市住房和城乡建设局通知所有在建工地停止施工，加固脚手架、塔吊等设施，撤离工地人员，做好临时工棚、围墙等防风加固工作。",
      "resources": [
        {
          "resource_type": "吊装设备",
          "quantity": 2
        },
        {
          "resource_type": "挖掘机",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 11,
      "time": "08:30",
      "role": "市公安局",
      "action": "交通管制",
      "description": "市公安局交警部门对沿海区域主要道路、桥梁、隧道实施交通管制，设置警示标志，引导车辆绕行，禁止无关车辆和人员进入危险区域。",
      "resources": [
        {
          "resource_type": "抢修车辆",
          "quantity": 3
        },
        {
          "resource_type": "通信设备",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 12,
      "time": "08:45",
      "role": "市水务局",
      "action": "排涝作业",
      "description": "市水务局组织排水队伍和排水设备对沿海低洼易涝区域开展排涝作业，清理排水管网和沟渠，预置排水泵等设备，做好强降雨积水防范工作。",
      "resources": [
        {
          "resource_type": "排水泵",
          "quantity": 10
        },
        {
          "resource_type": "抢修车辆",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 13,
      "time": "09:00",
      "role": "各街道办事处",
      "action": "安置点开放",
      "description": "各街道办事处开放辖区内应急避护场所和安置点，设置登记区、休息区、物资发放区，配备帐篷、折叠床、被褥、食品、饮用水等基本生活物资，做好转移群众接收安置工作。",
      "resources": [
        {
          "resource_type": "帐篷",
          "quantity": 50
        },
        {
          "resource_type": "急救包",
          "quantity": 20
        },
        {
          "resource_type": "发电机",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 14,
      "time": "09:15",
      "role": "市应急管理局",
      "action": "物资调配",
      "description": "市应急管理局根据各安置点需求，紧急调配帐篷、折叠床、被褥、食品、饮用水等救灾物资，组织运输车辆运往各安置点，保障转移群众基本生活。",
      "resources": [
        {
          "resource_type": "运输车辆",
          "quantity": 10
        },
        {
          "resource_type": "帐篷",
          "quantity": 100
        },
        {
          "resource_type": "急救包",
          "quantity": 50
        }
      ]
    },
    {
      "step_id": 15,
      "time": "09:30",
      "role": "市卫生健康局",
      "action": "医疗救护",
      "description": "市卫生健康局组织医疗机构派出救护车和医护人员，在各安置点和重点区域设置医疗救助点，配备急救药品和器械，做好伤员救治和卫生防疫准备。",
      "resources": [
        {
          "resource_type": "救护车",
          "quantity": 5
        },
        {
          "resource_type": "急救包",
          "quantity": 30
        }
      ]
    },
    {
      "step_id": 16,
      "time": "09:45",
      "role": "各街道办事处",
      "action": "险情巡查",
      "description": "各街道办事处组织人员对辖区内危旧房屋、低洼地带、地质灾害隐患点、户外广告牌、临时构筑物等开展巡查排查，发现险情及时处置并上报。",
      "resources": [
        {
          "resource_type": "无人机",
          "quantity": 3
        },
        {
          "resource_type": "通信设备",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 17,
      "time": "10:00",
      "role": "市自然资源局",
      "action": "隐患监测",
      "description": "市自然资源局对地质灾害隐患点开展监测预警，利用无人机和监测设备对山体滑坡、泥石流等隐患进行巡查，发现异常及时预警并组织人员撤离。",
      "resources": [
        {
          "resource_type": "无人机",
          "quantity": 5
        },
        {
          "resource_type": "环境监测设备",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 18,
      "time": "10:15",
      "role": "市水务局",
      "action": "水库调度",
      "description": "市水务局根据台风降雨预报，科学调度水库预泄腾库，降低水库水位，加强水库大坝巡查，确保水库安全运行。",
      "resources": [
        {
          "resource_type": "通信设备",
          "quantity": 3
        },
        {
          "resource_type": "抢修车辆",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 19,
      "time": "10:30",
      "role": "市供电局",
      "action": "电力保障",
      "description": "市供电局组织抢修队伍和发电设备，对重点区域和安置点提供应急供电保障，做好电力设施防风加固和故障抢修准备。",
      "resources": [
        {
          "resource_type": "发电机",
          "quantity": 10
        },
        {
          "resource_type": "抢修车辆",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 20,
      "time": "10:45",
      "role": "市通信管理局",
      "action": "通信保障",
      "description": "市通信管理局组织通信运营商做好通信设施防风加固和应急通信保障，预置卫星电话等应急通信设备，确保指挥通信畅通。",
      "resources": [
        {
          "resource_type": "卫星电话",
          "quantity": 10
        },
        {
          "resource_type": "通信设备",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 21,
      "time": "11:00",
      "role": "市应急管理局",
      "action": "应急队伍集结",
      "description": "市应急管理局集结消防、武警、民兵预备役等应急抢险救援队伍，清点人员装备，在重点区域预置抢险力量，做好抢险救援准备。",
      "resources": [
        {
          "resource_type": "消防车",
          "quantity": 10
        },
        {
          "resource_type": "冲锋舟",
          "quantity": 10
        },
        {
          "resource_type": "挖掘机",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 22,
      "time": "11:15",
      "role": "市应急管理局",
      "action": "灾情上报",
      "description": "市应急管理局收集汇总各县区、各部门防台风工作情况，包括人员转移、船只回港、险情处置等，按要求向上级应急管理部门报告灾情和防御工作动态。",
      "resources": [
        {
          "resource_type": "通信设备",
          "quantity": 3
        },
        {
          "resource_type": "卫星电话",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 23,
      "time": "11:30",
      "role": "市委宣传部",
      "action": "宣传引导",
      "description": "市委宣传部组织新闻媒体及时发布台风预警信息和防御指引，宣传防台风知识和避险常识，引导公众减少外出、远离危险区域，做好舆情监测和引导。",
      "resources": [
        {
          "resource_type": "通信设备",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 24,
      "time": "12:00",
      "role": "市三防指挥部",
      "action": "三停一休",
      "description": "市三防指挥部发布“三停一休”指令，要求沿海区域除抢险救灾和民生保障单位外，全面停工、停业、停课、休市，减少人员外出，确保安全。",
      "resources": [
        {
          "resource_type": "通信设备",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 25,
      "time": "12:30",
      "role": "各街道办事处",
      "action": "人员疏散引导",
      "description": "各街道办事处组织工作人员和志愿者对安置点群众进行秩序维护和生活服务，做好人员登记、物资发放、心理疏导等工作，确保安置点秩序稳定。",
      "resources": [
        {
          "resource_type": "帐篷",
          "quantity": 30
        },
        {
          "resource_type": "急救包",
          "quantity": 10
        },
        {
          "resource_type": "发电机",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 26,
      "time": "13:00",
      "role": "市公安局",
      "action": "治安维护",
      "description": "市公安局加强社会面治安巡逻防控，维护安置点、物资发放点等重点区域治安秩序，打击违法犯罪活动，确保社会稳定。",
      "resources": [
        {
          "resource_type": "巡逻车辆",
          "quantity": 10
        },
        {
          "resource_type": "通信设备",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 27,
      "time": "14:00",
      "role": "市应急管理局",
      "action": "灾损评估",
      "description": "市应急管理局组织各相关部门和专家对台风造成的灾害损失进行评估，包括人员伤亡、房屋倒损、基础设施损毁、农作物受灾等，形成灾损评估报告。",
      "resources": [
        {
          "resource_type": "无人机",
          "quantity": 5
        },
        {
          "resource_type": "环境监测设备",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 28,
      "time": "15:00",
      "role": "市三防指挥部",
      "action": "响应终止",
      "description": "台风影响减弱，市三防指挥部经会商研判，决定终止防台风应急响应，发布响应终止通知，转入灾后恢复重建阶段。",
      "resources": [
        {
          "resource_type": "通信设备",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 29,
      "time": "15:30",
      "role": "各相关部门",
      "action": "复工复课",
      "description": "各相关部门按照职责分工，组织做好灾后恢复工作，包括道路清障、电力通信抢修、供水排水恢复、卫生防疫、学校复课、企业复工等，尽快恢复正常生产生活秩序。",
      "resources": [
        {
          "resource_type": "抢修车辆",
          "quantity": 10
        },
        {
          "resource_type": "挖掘机",
          "quantity": 5
        },
        {
          "resource_type": "排水泵",
          "quantity": 10
        }
      ]
    }
  ]
